// Web layer: who can reach which URL
@Configuration
@EnableWebSecurity
@EnableMethodSecurity   // also turns on @PreAuthorize / @Secured on methods
public class SecurityConfig {

    @Bean
    SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        http.authorizeHttpRequests(auth -> auth
                .requestMatchers("/api/public/**").permitAll()
                .anyRequest().authenticated())
            .httpBasic(Customizer.withDefaults());
        return http.build();
    }
}

// Method layer: fine-grained role check inside a service
@Service
public class OrderService {

    @PreAuthorize("hasRole('MANAGER')")   // ignored unless @EnableMethodSecurity is present
    public void cancelOrder(Long id) {
        // ...only MANAGERs reach here
    }
}
```

`@EnableWebSecurity` guards the URLs; `@EnableMethodSecurity` makes the `@PreAuthorize` on `cancelOrder` actually enforce — remove it and the check is silently skipped.

@Configuration
@EnableWebSecurity
public class SecurityConfig {

    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        http
            .authorizeHttpRequests(auth -> auth
                .requestMatchers("/api/public/**").permitAll()  // No auth needed
                .requestMatchers("/api/admin/**").hasRole("ADMIN")  // ADMIN role required
                .anyRequest().authenticated()  // Everything else needs authentication
            )
            .httpBasic(Customizer.withDefaults());  // Enable HTTP Basic authentication
        return http.build();
    }

    @Bean
    public UserDetailsService userDetailsService() {
        var admin = User.withUsername("admin")
            .password("{noop}admin123")  // {noop} = no password encoding (dev only)
            .roles("ADMIN")
            .build();
        return new InMemoryUserDetailsManager(admin);  // In-memory user for testing
    }
}

@Configuration
@EnableWebSecurity
@EnableMethodSecurity  // For @PreAuthorize on methods
public class RestSecurityConfig {

    private final JwtAuthenticationFilter jwtFilter;

    @Bean
    public SecurityFilterChain apiFilterChain(HttpSecurity http) throws Exception {
        http
            .csrf(csrf -> csrf.disable())  // No CSRF for stateless REST APIs
            .sessionManagement(session -> 
                session.sessionCreationPolicy(SessionCreationPolicy.STATELESS))  // No sessions
            .authorizeHttpRequests(auth -> auth
                .requestMatchers("/api/auth/**").permitAll()  // Login/register endpoints
                .requestMatchers("/api/admin/**").hasRole("ADMIN")
                .anyRequest().authenticated()
            )
            .addFilterBefore(jwtFilter, UsernamePasswordAuthenticationFilter.class)  // JWT before auth
            .exceptionHandling(ex -> ex
                .authenticationEntryPoint(new RestAuthenticationEntryPoint())  // Custom 401 JSON
                .accessDeniedHandler(new RestAccessDeniedHandler())  // Custom 403 JSON
            );
        return http.build();
    }

    @Bean
    public PasswordEncoder passwordEncoder() {
        return new BCryptPasswordEncoder();  // Always hash passwords
    }
}

